#!/usr/bin/env bash
set -euo pipefail

# Generated by fallow setup-hooks.
# Installer version: 3.31.0
# Local deviations, re-apply after `fallow hooks install` regenerates this
# file: the FALLOW_AUDIT_BASE default (#21), the target checkout block plus
# its tokenizer lines (#44), and the coverage map block (#45), each marked
# below.
# Requires bash and jq. On Windows run via git-bash or WSL.
# Blocks Claude Code git commit and git push when fallow audit returns verdict fail.
# Runtime errors fail open with a single stderr notice so skips stay visible.
# Set FALLOW_GATE_DEBUG=1 to also log when a command is skipped because it is
# not classified as a git commit or push.
#
# Version floor (FALLOW_GATE_MIN_VERSION, default 2.85.0). The gate passes
# --gate-marker agent (added in v2.85.0) so Impact can record containment;
# older binaries reject the flag entirely, which would make every audit fail
# open. The floor also covers the older uncommitted-changes inclusion fix
# (aabb8e1b, v2.46.0). Set the env var to the empty string to disable.
# Floor comparison uses `sort -V`; GNU and BSD agree on plain semver but
# diverge on prereleases (BSD sorts `2.48.0-alpha.1` ABOVE `2.48.0`, GNU below).
# If you set a prerelease floor explicitly, verify the behavior on the target OS.

if ! command -v jq >/dev/null 2>&1; then
  echo "fallow-gate: jq not on PATH, skipping audit." >&2
  exit 0
fi

INPUT="$(cat)"
CMD="$(jq -r '.tool_input.command // empty' <<<"$INPUT")"

# Tokenize instead of matching one regex so git-level options between `git`
# and the subcommand (git -c k=v commit, git -C dir push, git --no-pager
# commit, git --git-dir=/x push) still route into the audit, while subcommand
# lookalikes in arguments (git log commit-message.txt) do not. See issue #2106.
is_git_write_command() {
  local cmd="$1" segment
  # effect-schema-ext #44: see "Target checkout" below for these two arrays.
  GATE_CD_ARGS=()
  GATE_GIT_C_ARGS=()
  # Control operators separate simple commands; each becomes its own line.
  while IFS= read -r segment; do
    # Intentional word splitting; globbing is disabled below.
    # shellcheck disable=SC2086
    set -- $segment
    # effect-schema-ext #44: a segment that is a `cd` moves the git command
    # that follows it; record the destination word (`~` for a bare `cd`).
    if [ "${1:-}" = "cd" ]; then
      shift
      if [ "${1:-}" = "--" ]; then
        shift
      fi
      GATE_CD_ARGS+=("${1-~}")
    fi
    while [ "$#" -gt 0 ]; do
      if [ "$1" != "git" ]; then
        shift
        continue
      fi
      shift
      GATE_GIT_C_ARGS=() # effect-schema-ext #44: only the matched git's -C counts.
      while [ "$#" -gt 0 ]; do
        case "$1" in
          commit | push)
            return 0
            ;;
          -c | -C | --git-dir | --work-tree | --namespace | --config-env | --super-prefix | --exec-path | --list-cmds | --attr-source)
            # Global option whose value arrives as the next word.
            if [ "$1" = "-C" ] && [ "$#" -gt 1 ]; then
              GATE_GIT_C_ARGS+=("$2") # effect-schema-ext #44
            fi
            shift
            [ "$#" -gt 0 ] && shift
            ;;
          -*)
            # Value-less global option (--no-pager) or inline-value form
            # (--git-dir=/x, -cuser.name=x).
            shift
            ;;
          *)
            # A different subcommand; resume scanning for a later `git` word.
            break
            ;;
        esac
      done
    done
  done < <(printf '%s\n' "$cmd" | tr ';|&()' '\n\n\n\n\n')
  return 1
}

set -f
if is_git_write_command "$CMD"; then
  GIT_WRITE=1
else
  GIT_WRITE=0
fi
set +f
if [ "$GIT_WRITE" -eq 0 ]; then
  if [ -n "${FALLOW_GATE_DEBUG:-}" ]; then
    echo "fallow-gate: not a git commit/push, skipping audit." >&2
  fi
  exit 0
fi

# --- Target checkout: local deviation from the generated script (effect-schema-ext #44) ---
# The generated gate audits the hook process's working directory, which is the
# session's project dir, not the checkout the git command writes to. AGENTS.md
# has agents commit from worktrees under .claude/worktrees/, so a
# `git -C <worktree> commit` or `cd <worktree> && git commit` was never audited.
# Resolve the target the way the shell and git would: start from the hook
# input's `cwd` (the directory Claude is working in; this process's cwd if
# absent), apply each `cd <dir>` segment before the matched git command, then
# each of that git's `-C <dir>` options, relative paths against the previous
# step. The tokenizer above records the words (its "effect-schema-ext #44"
# lines). Audit from that checkout's top level. When a word cannot be resolved
# statically (a variable, a substitution, a quoted path with spaces, `cd -`,
# `cd` options) or the result is not inside a git work tree, keep the generated
# behaviour (audit here) and say so on stderr. The tokenizer treats `(` and
# `)` as plain separators, so it cannot tell whether a `cd` runs inside a
# subshell (`(cd a && make) && git commit`, `x=$(cd a && pwd); git commit`),
# where it does not move the git command. A command that records a `cd` and
# contains `(` therefore keeps the generated behaviour too, rather than risk
# auditing a checkout the commit does not touch.
# `fallow hooks install --target agent --agent claude` overwrites this script
# without asking, so re-apply this block and the tokenizer lines after
# regenerating.
gate_resolve_dir() {
  # $1: directory so far; $2: a `cd` or `-C` word. Prints the new directory.
  local base="$1" word="$2"
  case "$word" in
    \"*\" | \'*\') word="${word:1:${#word}-2}" ;;
  esac
  case "$word" in
    '') printf '%s\n' "$base" ;; # `-C ""` and `cd ""` leave the directory as is.
    \~) printf '%s\n' "${HOME:?}" ;;
    \~/*) printf '%s\n' "${HOME:?}/${word#\~/}" ;;
    -* | \~* | *[\$\`\"\'\\\*\?\[]*) return 1 ;;
    /*) printf '%s\n' "$word" ;;
    *) printf '%s\n' "$base/$word" ;;
  esac
}

GATE_TARGET="$(jq -r '.cwd // empty' <<<"$INPUT")"
GATE_TARGET="${GATE_TARGET:-$PWD}"
GATE_UNRESOLVED=""
for GATE_WORD in ${GATE_CD_ARGS[@]+"${GATE_CD_ARGS[@]}"} ${GATE_GIT_C_ARGS[@]+"${GATE_GIT_C_ARGS[@]}"}; do
  if ! GATE_TARGET="$(gate_resolve_dir "$GATE_TARGET" "$GATE_WORD")"; then
    GATE_UNRESOLVED="'$GATE_WORD'"
    break
  fi
done
case "$CMD" in
  *'('*)
    if [ -z "$GATE_UNRESOLVED" ] && [ "${#GATE_CD_ARGS[@]}" -gt 0 ]; then
      GATE_UNRESOLVED="a cd in a command with a subshell"
    fi
    ;;
esac
if [ -n "$GATE_UNRESOLVED" ]; then
  echo "fallow-gate: cannot resolve the target directory from $GATE_UNRESOLVED; auditing $PWD." >&2
elif GATE_TOP="$(git -C "$GATE_TARGET" rev-parse --show-toplevel 2>/dev/null)" && [ -n "$GATE_TOP" ] && cd "$GATE_TOP"; then
  if [ -n "${FALLOW_GATE_DEBUG:-}" ]; then
    echo "fallow-gate: auditing $GATE_TOP." >&2
  fi
else
  echo "fallow-gate: $GATE_TARGET is not inside a git work tree; auditing $PWD." >&2
fi
# --- End target checkout (effect-schema-ext #44) ---

# A real installed Git hook keeps its caller's PATH and does not add
# node_modules/.bin, so a project-local install is invisible to `command -v`.
# The arms below cover the layouts a project-local install can take, in the
# order they are cheapest to probe. Keep them in step with the Lefthook job
# `fallow init --hooks` prints: the two must resolve the same installs.
if command -v fallow >/dev/null 2>&1; then
  RUNNER=(fallow)
  BIN_DESC="$(command -v fallow)"
elif [ -x ./node_modules/.bin/fallow ]; then
  RUNNER=(./node_modules/.bin/fallow)
  BIN_DESC="./node_modules/.bin/fallow"
elif command -v yarn >/dev/null 2>&1 && YARN_BIN="$(yarn bin fallow 2>/dev/null)" && [ -n "$YARN_BIN" ]; then
  # Yarn Plug'n'Play has no node_modules/.bin at all, so neither the launcher
  # check above nor npx can see the install.
  RUNNER=(yarn exec fallow --)
  BIN_DESC="yarn exec fallow"
elif command -v npx >/dev/null 2>&1 && VER_PROBE="$(npx --no-install fallow --version 2>/dev/null || true)" && [[ "$VER_PROBE" == fallow* ]]; then
  RUNNER=(npx --no-install fallow)
  BIN_DESC="npx --no-install fallow"
else
  echo "fallow-gate: fallow binary not found (tried PATH, node_modules/.bin, yarn and npx --no-install), skipping audit." >&2
  exit 0
fi

VERSION_RAW="$("${RUNNER[@]}" --version 2>/dev/null || true)"
VERSION="${VERSION_RAW#fallow }"
VERSION="${VERSION%% *}"

MIN_VERSION="${FALLOW_GATE_MIN_VERSION-2.85.0}"
if [ -n "$MIN_VERSION" ] && [ -n "$VERSION" ]; then
  LOWER="$(printf '%s\n%s\n' "$MIN_VERSION" "$VERSION" | sort -V | head -n1)"
  if [ "$LOWER" != "$MIN_VERSION" ]; then
    {
      echo "fallow-gate: blocked: $BIN_DESC is fallow $VERSION, below required $MIN_VERSION."
      echo "fallow-gate: older binaries reject the --gate-marker flag this gate passes"
      echo "fallow-gate: (added in fallow v2.85.0), so the audit cannot run."
      echo "fallow-gate: upgrade the fallow on PATH (e.g. npm install -g fallow@latest or"
      echo "fallow-gate: cargo install fallow-cli), or set FALLOW_GATE_MIN_VERSION= to disable."
    } >&2
    exit 2
  fi
fi

TMP_JSON="$(mktemp)"
TMP_ERR="$(mktemp)"
GATE_COV_LOG="" # effect-schema-ext #45: the coverage run's log, if any.
cleanup() {
  rm -f "$TMP_JSON" "$TMP_ERR" ${GATE_COV_LOG:+"$GATE_COV_LOG"}
}
trap cleanup EXIT

# Local deviation from the generated script (effect-schema-ext #21): pin the
# audit base to origin/trunk unless FALLOW_AUDIT_BASE is already set. fallow's
# default (merge-base with the branch's upstream, else origin/HEAD, origin/main
# or origin/master) is wrong here twice over: once a branch is pushed with -u its
# upstream is its own remote branch, so the audit compares HEAD with itself and
# misses every pushed commit; and with no upstream in a checkout without
# origin/HEAD (no main or master exists) it cannot detect a base at all, errors
# and fails open. `fallow hooks install --target agent --agent claude`
# overwrites this script without asking, so re-apply this after regenerating.
export FALLOW_AUDIT_BASE="${FALLOW_AUDIT_BASE:-origin/trunk}"

# --- Coverage map: local deviation from the generated script (effect-schema-ext #45) ---
# .fallowrc.json's `health.coverage` makes the audit read an Istanbul map that
# `vp run test:coverage` writes and git ignores. The generated gate fails open
# when the audit cannot run, so with no map (every fresh clone or worktree) the
# audit errors on the missing file and every commit passed silently; and a map
# whose absolute paths name another checkout matches no file, so a CRAP-72
# function passed. Here the gate regenerates the map, from the directory the
# audit runs in, when it is:
#   - missing, empty, unreadable, or not a JSON object;
#   - keyed by a path outside this checkout's packages/ (`pwd -P`). Anchored
#     at packages/, not the checkout root: a map from a worktree nested under
#     .claude/worktrees/ also starts with this checkout's path;
#   - older than any input of the coverage run: packages/*/src and
#     packages/*/tests (files and directories, so a deleted or renamed file
#     counts), the vite configs and the lockfile. Compared by mtime: an edit,
#     a `git checkout` or a rebase writes the working tree, and both the audit
#     and the coverage run read the working tree, staged or not. A tool that
#     restores an old mtime (`cp -p`, `tar -x`) can hide a change. Not
#     watched, as they rarely change test results: tsconfig*.json,
#     packages/*/package.json and pnpm-workspace.yaml.
# The root `test:coverage` task is `cache: false`, so this check is its cache;
# a fresh map costs one `find` and one `jq`. `vp` is found like fallow above
# (PATH, then node_modules/.bin), and only where node_modules exists: the
# session's `vp` shim falls back to another checkout's vite-plus otherwise. If
# that fails, the run fails (a failing test or threshold) or the map is still
# stale after it, the gate blocks with exit 2 and says what to run, rather
# than fail open: Claude Code shows a hook's stderr only on exit 2. The run's
# output goes to a temp file and only its tail is shown on failure. Skipped
# when no .fallowrc.json here sets `health.coverage` (read with jq, so a move
# to fallow.toml or a JSONC config would skip it silently and reopen #45), and
# when this checkout's vite.config.ts defines no `test:coverage` task: the
# paths and the task are this repo's layout, so a checkout #44 resolved to some
# other repo keeps the generated behaviour. This block sits after
# the fallow lookup, so a checkout with no fallow skips as generated without
# paying for a coverage run.
# `fallow hooks install --target agent --agent claude` overwrites this script
# without asking, so re-apply this block after regenerating.
gate_coverage_stale() {
  # $1: the map's absolute path. Prints why it is stale; prints nothing if fresh.
  if [ ! -s "$1" ]; then
    echo "missing"
  elif [ "$(jq -r --arg root "$GATE_COV_ROOT/packages/" 'type == "object" and length > 0 and (keys_unsorted | all(startswith($root)))' "$1" 2>/dev/null || true)" != "true" ]; then
    echo "unreadable, empty or keyed by paths outside $GATE_COV_ROOT/packages"
  elif [ -n "$(find packages/*/src packages/*/tests packages/*/vite.config.ts vite.config.ts vite.package.ts pnpm-lock.yaml -newer "$1" -print -quit 2>/dev/null || true)" ]; then
    # An unmatched glob or a missing path is skipped (find's error is discarded).
    echo "older than the source, tests or config"
  fi
}

GATE_COV_PATH=""
if [ -f .fallowrc.json ] && grep -q '"test:coverage"' vite.config.ts 2>/dev/null; then
  GATE_COV_PATH="$(jq -r '.health.coverage // empty' .fallowrc.json 2>/dev/null || true)"
fi
if [ -n "$GATE_COV_PATH" ]; then
  GATE_COV_ROOT="$(pwd -P)"
  case "$GATE_COV_PATH" in
    /*) GATE_COV_MAP="$GATE_COV_PATH" ;;
    *) GATE_COV_MAP="$GATE_COV_ROOT/$GATE_COV_PATH" ;;
  esac
  GATE_COV_WHY="$(gate_coverage_stale "$GATE_COV_MAP")"
  if [ -n "$GATE_COV_WHY" ]; then
    GATE_VP=""
    if [ -d node_modules ]; then
      if command -v vp >/dev/null 2>&1; then
        GATE_VP="vp"
      elif [ -x ./node_modules/.bin/vp ]; then
        GATE_VP="./node_modules/.bin/vp"
      fi
    fi
    if [ -z "$GATE_VP" ]; then
      {
        echo "fallow-gate: blocked: the coverage map $GATE_COV_PATH is $GATE_COV_WHY,"
        echo "fallow-gate: and the gate cannot regenerate it: no node_modules or no vp in"
        echo "fallow-gate: $GATE_COV_ROOT. Without a current map the audit misjudges"
        echo "fallow-gate: every function's CRAP score. There, run \`pnpm install\` and then"
        echo "fallow-gate: \`vp run test:coverage\`, and retry."
      } >&2
      exit 2
    fi
    GATE_COV_LOG="$(mktemp)"
    if "$GATE_VP" run test:coverage </dev/null >"$GATE_COV_LOG" 2>&1; then
      GATE_COV_STATUS=0
    else
      GATE_COV_STATUS=$?
    fi
    GATE_COV_AFTER=""
    if [ "$GATE_COV_STATUS" -eq 0 ]; then
      GATE_COV_AFTER="$(gate_coverage_stale "$GATE_COV_MAP")"
    fi
    if [ "$GATE_COV_STATUS" -ne 0 ] || [ -n "$GATE_COV_AFTER" ]; then
      {
        echo "fallow-gate: blocked: the coverage map $GATE_COV_PATH was $GATE_COV_WHY."
        if [ "$GATE_COV_STATUS" -ne 0 ]; then
          echo "fallow-gate: \`$GATE_VP run test:coverage\` in $GATE_COV_ROOT exited $GATE_COV_STATUS."
        else
          echo "fallow-gate: \`$GATE_VP run test:coverage\` in $GATE_COV_ROOT passed, but the map"
          echo "fallow-gate: is still $GATE_COV_AFTER (check .fallowrc.json health.coverage"
          echo "fallow-gate: against the coverage reportsDirectory in vite.config.ts)."
        fi
        echo "fallow-gate: fix it, check \`vp run test:coverage\` passes, and retry. Its last 40 lines:"
        tail -n 40 "$GATE_COV_LOG"
      } >&2
      rm -f "$GATE_COV_LOG"
      exit 2
    fi
    rm -f "$GATE_COV_LOG"
    if [ -n "${FALLOW_GATE_DEBUG:-}" ]; then
      echo "fallow-gate: regenerated $GATE_COV_PATH (was $GATE_COV_WHY)." >&2
    fi
  fi
fi
# --- End coverage map (effect-schema-ext #45) ---

if "${RUNNER[@]}" audit --format json --quiet --explain --gate-marker agent >"$TMP_JSON" 2>"$TMP_ERR"; then
  STATUS=0
else
  STATUS=$?
fi

VERDICT="$(jq -r '.verdict // empty' <"$TMP_JSON" 2>/dev/null || true)"
IS_ERROR="$(jq -r '.error // false' <"$TMP_JSON" 2>/dev/null || echo false)"

if [ "$VERDICT" = "fail" ]; then
  echo "fallow-gate: blocked by fallow ${VERSION:-unknown} at $BIN_DESC" >&2
  cat "$TMP_JSON" >&2
  exit 2
fi

if [ "$STATUS" -eq 2 ] || [ "$IS_ERROR" = "true" ]; then
  MSG="$(jq -r '.message // empty' <"$TMP_JSON" 2>/dev/null || true)"
  if [ -n "$MSG" ]; then
    echo "fallow-gate: fallow audit runtime error ($MSG), skipping." >&2
  else
    echo "fallow-gate: fallow audit runtime error, skipping." >&2
  fi
  exit 0
fi

if [ "$STATUS" -ne 0 ]; then
  ERR_LINE="$(sed -n '1p' "$TMP_ERR" 2>/dev/null || true)"
  if [ -n "$ERR_LINE" ]; then
    echo "fallow-gate: fallow audit exited $STATUS ($ERR_LINE), skipping." >&2
  else
    echo "fallow-gate: fallow audit exited $STATUS, skipping." >&2
  fi
  exit 0
fi

exit 0
